;qualified_name&quot;:&quot;workspace-linux.drivers.usb.typec.class.typec_register_partner&quot;,&quot;label&quot;:&quot;Function&quot;,&quot;file_path&quot;:&quot;/workspace/linux/drivers/usb/typec/class.c&quot;,&quot;start_line&quot;:1106,&quot;end_line&quot;:1165,&quot;source&quot;:&quot;struct typec_partner *typec_register_partner(struct typec_port *port,
